25	\includegraphics[width=0.85\textwidth]{slides-images/slide-12.jpg}
26	\caption{Universal Approximation Theorem 示意图\protect\footnotemark}
27	\end{figure}
28	\footnotetext{Slides 第12页。引用 Hornik+ Neural Networks 1989。}
